43	// Bounds, overridable only for tests (the env names are the engine's, not a pack's).
44	const TIMEOUT_MS = Number(process.env.CLAUDINITE_PACK_STEP_TIMEOUT_MS) || 20_000;
45	const MAX_BYTES = Number(process.env.CLAUDINITE_PACK_STEP_MAX_BYTES) || 32_768;
