50	  const loaderDir = dirname(fileURLToPath(import.meta.url)); // <corpus>/engine/pack_loader
51	  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
52	
53	  let config = { packs: [] };
54	  const configPath = join(projectRoot, '.claudinite-checks.json');
55	  if (existsSync(configPath)) {
56	    try { config = JSON.parse(readFileSync(configPath, 'utf8')); } catch { return; } // unparsable settings are the world runner's finding
57	  }
58	
