76	    const run = spawnSync(process.execPath, [step], {
77	      cwd: projectRoot,
78	      encoding: 'utf8',
79	      timeout: TIMEOUT_MS,
80	      maxBuffer: MAX_BYTES * 4, // room to notice an over-cap step rather than erroring on it
