  }
}

// Fail-soft to the end: a broken registry, an unreadable pack tree, anything —
// one note, exit 0.
main()
  .catch((e) => note(`the pack session-start runner could not complete (${e.message}) — continuing.`))
  .finally(() => process.exit(0));

